%% ========================================================================
%  UAV-assisted vehicular network simulation
%  MODIFIED VERSION - adds:
%   (1) Hybrid LOS/NLOS propagation model driven by an obstacle region and
%       a 3GPP TR38.901-style probabilistic LOS model (per-link, per-step,
%       instead of one global LOS flag for the whole simulation).
%   (2) Spatially-correlated log-normal shadow fading, different sigma for
%       LOS vs NLOS links.
%   (3) Per-vehicle small-scale fading channel profile selection
%       (CDL-D when the link is LOS, CDL-A when it is NLOS) inside the
%       PDSCH link-level loop, instead of a single global "channel" object.
%   (4) A selectable UAV1 (proposed) objective:
%         'mean'     -> maximize average SNR (original formulation)
%         'maxmin'   -> maximize the worst-served vehicle's SNR (fairness)
%         'weighted' -> maximize a QoS/priority-weighted SNR sum
%       to create the "heterogeneous user requirements" scenario asked by
%       Reviewer 1.
%   (5) Bug fixes:
%       - The parfor loops used a stale `vehicleID` (leftover from the
%         previous serial for-loop) inside `ismember(vehicleID, carsInSim)`,
%         which was always true and unrelated to loop index i. Replaced by
%         the correct `~isnan(stepSNRs_*(i))` check.
%       - `posX_dron_Movil` was never updated after moving the UAV (only
%         `posY_dron_Movil` was). It self-corrected every step because the
%         next iteration re-reads the POI position from SUMO, but is now
%         fixed explicitly for clarity/robustness.
%
%  HOW TO REPRODUCE THE THREE REVIEWER SCENARIOS
%   Scenario A (original, LOS-dominant, CDL-D):
%       simParameters.Obstacle.Enable      = false;
%       simParameters.UseProbabilisticLOS  = false;
%       simParameters.DelayProfileLOS      = 'CDL-D';
%       simParameters.DelayProfileNLOS     = 'CDL-D';   % irrelevant, forced LOS
%       simParameters.UAV1Objective        = 'mean';
%
%   Scenario B (NLOS-dominant / obstructed corridor):
%       simParameters.Obstacle.Enable      = true;
%       simParameters.UseProbabilisticLOS  = true;
%       simParameters.DelayProfileLOS      = 'CDL-D';
%       simParameters.DelayProfileNLOS     = 'CDL-A';
%       simParameters.UAV1Objective        = 'mean';
%
%   Scenario C (heterogeneous QoS requirements):
%       same as B, but
%       simParameters.UAV1Objective        = 'maxmin';   % or 'weighted'
%
%   IMPORTANT: simParameters.Obstacle.X / .Y are in the same (X,Y)
%   coordinate frame as traci.vehicle.getPosition / traci.poi.getPosition.
%   Tune them to an actual obstructed region of YOUR SUMO map (e.g. a
%   building block, an underpass, dense foliage) - the example values
%   below are placeholders based on the [0,1500]x[500,1000] bounding box
%   used in your heatmap figure and must be adjusted to your scenario.
%% ========================================================================

clc
clear variables
close all
tic

%% Variables de almacenamiento
num_iterations = 20;
snr_all_iterations = cell(num_iterations, 4);
bler_all_iterations = cell(num_iterations, 4);
throughput_all_iterations = cell(num_iterations, 4);

divisor = 1;

edges = {'153180751', '201283198', '476297344', '476297343', '153180753', '145354574', ...
    '201278920', '153177808', '153177822', 'medio1_2', '153190004', '153189996'};
num_edges = length(edges);
tiempo_simulacion = 150;
densidades_iteraciones = zeros(num_iterations, tiempo_simulacion);

for iter = 1:num_iterations %[output:group:0640207d]

    traci.start('sumo-gui -c ./highway_bremen_1dir_low.sumocfg --start --random');

    densidades_totales = [];

    %% UAV: fixed, circular and mobile POIs
    pos_inicialX = 1017.7;
    pos_inicialY = 767;

    poiID_Fijo = 'Dron_Fijo';
    traci.poi.add(poiID_Fijo, pos_inicialY, pos_inicialX, [0, 0, 255, 255], 'Circle', 10);

    poiID_Predefinido = 'Dron_Predefinido';
    traci.poi.add(poiID_Predefinido, pos_inicialY, pos_inicialX, [255, 0, 0, 255], 'Circle', 10);
    posiciones = [
        pos_inicialX, pos_inicialY;
        1062.99, 678.15;
        810.23, 518.35;
        1363.55, 867.54;
        ];
    velocidad = 20/divisor;
    posicion_actual = 1;
    direccion = 1;
    posX_dron_predefinido = posiciones(posicion_actual, 1);
    posY_dron_predefinido = posiciones(posicion_actual, 2);

    poiID_Movil = 'Dron_Movil';
    traci.poi.add(poiID_Movil, pos_inicialY, pos_inicialX, [128, 0, 128, 255], 'Circle', 10);

    Vel_dron = 0;
    Vel_dron_Cen = 0;
    acel_max = 2.5/divisor;
    Vel_max = 23/divisor;
    if acel_max == 0
        Vel_dron = 22;
    end

    poiID_Cen = 'Dron_Centroide';
    traci.poi.add(poiID_Cen, pos_inicialY, pos_inicialX, [126, 47, 142, 255], 'Circle', 10);

    tiempo = 1;

    pos3D_history_Movil = [];
    pos3D_history_Cen = [];
    SNRs_Movil = [];
    SNRs_Cen = [];
    promedioSNR_Movil = [];
    promedioSNR_Cen = [];

    % NUEVO: estado de shadow fading espacialmente correlado, por vehiculo,
    % separado para el enlace del dron movil y el del dron centroide.
    shadowState_Movil = containers.Map('KeyType', 'char', 'ValueType', 'any');
    shadowState_Cen   = containers.Map('KeyType', 'char', 'ValueType', 'any');

    %% Creacion del sistema de comunicacion
    simParameters = struct();
    simParameters.NFrames = 1;
    simParameters.PerfectChannelEstimator = true;
    simParameters.DisplaySimulationInformation = false;
    simParameters.DisplayDiagnostics = false;
    simParameters.Carrier = nrCarrierConfig;
    simParameters.Carrier.NSizeGrid = 32;
    simParameters.Carrier.SubcarrierSpacing = 120;
    simParameters.Carrier.CyclicPrefix = 'Normal';
    simParameters.Carrier.NCellID = 1;
    simParameters.CarrierFrequency = 26e9;
    simParameters.TxHeight = 100;
    simParameters.TxPower = 25;
    simParameters.RxHeight = 1.5;
    simParameters.RxNoiseFigure = 9;
    simParameters.RxAntTemperature = 290;
    simParameters.PathLossModel = '5G-NR';
    simParameters.PathLoss = nrPathLossConfig;
    simParameters.PathLoss.Scenario = 'RMa';
    simParameters.PathLoss.EnvironmentHeight = 0;

    % ---------------------------------------------------------------
    % NUEVO: modelo hibrido de propagacion LOS/NLOS
    % ---------------------------------------------------------------
    simParameters.DelayProfileLOS  = 'CDL-D';   % perfil de fading para enlaces LOS
    simParameters.DelayProfileNLOS = 'CDL-A';   % perfil de fading para enlaces NLOS
    % DelayProfile "nominal" solo se usa para la config inicial de
    % validacion del canal (numero de antenas, etc.), el canal real usado
    % por cada vehiculo se construye por enlace en el bucle PDSCH.
    simParameters.DelayProfile = simParameters.DelayProfileLOS;

    simParameters.MaximumDopplerShift = 5;
    simParameters.DelaySpread = 300e-9;

    % Shadow fading (dB), sigma distinto para LOS/NLOS
    simParameters.ShadowSigmaLOS  = 4;
    simParameters.ShadowSigmaNLOS = 8;

    % Distancia de correlacion espacial del shadow fading (m)
    simParameters.CorrDistance = 40;

    % Region de obstaculo que bloquea LOS de forma determinista.
    % AJUSTAR a la geometria real de tu mapa SUMO.
    simParameters.Obstacle.Enable = true;
    simParameters.Obstacle.X = [900 1100];
    simParameters.Obstacle.Y = [650 850];

    % Modelo de probabilidad de LOS (3GPP TR38.901, escenario RMa) fuera
    % de la zona de obstaculo determinista.
    simParameters.UseProbabilisticLOS = true;

    % Objetivo del UAV1 (dron propuesto): 'mean' | 'maxmin' | 'weighted'
    simParameters.UAV1Objective = 'mean';
    % ---------------------------------------------------------------

    simParameters.NTxAnts = 1;
    simParameters.NRxAnts = 1;

    simParameters.PDSCH = nrPDSCHConfig;
    simParameters.PDSCHExtension = struct();
    simParameters.PDSCH.PRBSet = 0:simParameters.Carrier.NSizeGrid-1;
    simParameters.PDSCH.SymbolAllocation = [0, simParameters.Carrier.SymbolsPerSlot];
    simParameters.PDSCH.MappingType = 'A';
    simParameters.PDSCH.NID = simParameters.Carrier.NCellID;
    simParameters.PDSCH.RNTI = 1;
    simParameters.PDSCH.VRBToPRBInterleaving = 0;
    simParameters.PDSCH.VRBBundleSize = 4;
    simParameters.PDSCH.NumLayers = 1;

    if simParameters.PDSCH.NumCodewords > 1
        simParameters.PDSCH.Modulation = {'16QAM','16QAM'};
        simParameters.PDSCHExtension.TargetCodeRate = [490 490]/1024;
    else
        simParameters.PDSCH.Modulation = '16QAM';
        simParameters.PDSCHExtension.TargetCodeRate = 490/1024;
    end

    simParameters.PDSCH.DMRS.DMRSPortSet = 0:simParameters.PDSCH.NumLayers-1;
    simParameters.PDSCH.DMRS.DMRSTypeAPosition = 2;
    simParameters.PDSCH.DMRS.DMRSLength = 1;
    simParameters.PDSCH.DMRS.DMRSAdditionalPosition = 2;
    simParameters.PDSCH.DMRS.DMRSConfigurationType = 2;
    simParameters.PDSCH.DMRS.NumCDMGroupsWithoutData = 1;
    simParameters.PDSCH.DMRS.NIDNSCID = 1;
    simParameters.PDSCH.DMRS.NSCID = 0;

    simParameters.PDSCH.EnablePTRS = 0;
    simParameters.PDSCH.PTRS.TimeDensity = 1;
    simParameters.PDSCH.PTRS.FrequencyDensity = 2;
    simParameters.PDSCH.PTRS.REOffset = '00';
    simParameters.PDSCH.PTRS.PTRSPortSet = [];

    simParameters.PDSCH.ReservedPRB{1}.SymbolSet = [];
    simParameters.PDSCH.ReservedPRB{1}.PRBSet = [];
    simParameters.PDSCH.ReservedPRB{1}.Period = [];

    simParameters.PDSCHExtension.PRGBundleSize = [];
    simParameters.PDSCHExtension.XOverhead = 6 * simParameters.PDSCH.EnablePTRS;
    simParameters.PDSCHExtension.NHARQProcesses = 16;
    simParameters.PDSCHExtension.EnableHARQ = true;

    simParameters.PDSCHExtension.LDPCDecodingAlgorithm = 'Normalized min-sum';
    simParameters.PDSCHExtension.MaximumLDPCIterationCount = 6;
    simParameters.DataType = 'single';

    % Canal "nominal" solo para validar geometria de antenas y obtener
    % waveformInfo / chInfo iniciales. El canal realmente usado por cada
    % vehiculo se reconstruye por enlace (ver buildLocalChannel).
    if contains(simParameters.DelayProfile,'CDL','IgnoreCase',true)
        channel = nrCDLChannel;
        channel = hArrayGeometry(channel, simParameters.NTxAnts, simParameters.NRxAnts);
        simParameters.NTxAnts = prod(channel.TransmitAntennaArray.Size);
        simParameters.NRxAnts = prod(channel.ReceiveAntennaArray.Size);
    else
        channel = nrTDLChannel;
        channel.NumTransmitAntennas = simParameters.NTxAnts;
        channel.NumReceiveAntennas = simParameters.NRxAnts;
    end
    channel.DelayProfile = simParameters.DelayProfile;
    chInfo = info(channel);
    if contains(simParameters.DelayProfile,'CDL','IgnoreCase',true)
        kFactor = chInfo.KFactorFirstCluster;
    else
        kFactor = chInfo.KFactorFirstTap;
    end
    % NOTA: ya no se usa un unico simParameters.LOS global para todo el
    % enlace/toda la simulacion. Se deja este calculo solo como
    % diagnostico informativo del perfil nominal.
    simParameters.LOS_nominal = kFactor > -inf; %#ok<NASGU>

    waveformInfo = nrOFDMInfo(simParameters.Carrier);
    channel.DelaySpread = simParameters.DelaySpread;
    channel.MaximumDopplerShift = simParameters.MaximumDopplerShift;
    channel.SampleRate = waveformInfo.SampleRate;
    maxChDelay = chInfo.MaximumChannelDelay;

    validateNumLayers(simParameters);

    if simParameters.PDSCHExtension.EnableHARQ
        rvSeq = [0 2 3 1];
    else
        rvSeq = 0;
    end

    encodeDLSCH = nrDLSCH;
    encodeDLSCH.MultipleHARQProcesses = true;
    encodeDLSCH.TargetCodeRate = simParameters.PDSCHExtension.TargetCodeRate;

    decodeDLSCH = nrDLSCHDecoder;
    decodeDLSCH.MultipleHARQProcesses = true;
    decodeDLSCH.TargetCodeRate = simParameters.PDSCHExtension.TargetCodeRate;
    decodeDLSCH.LDPCDecodingAlgorithm = simParameters.PDSCHExtension.LDPCDecodingAlgorithm;
    decodeDLSCH.MaximumLDPCIterationCount = simParameters.PDSCHExtension.MaximumLDPCIterationCount;

    % NUEVO: N0 y fftOccupancy son constantes (no dependen de posiciones),
    % se calculan una sola vez por iteracion en vez de recalcularlas en
    % cada paso/vehiculo como en el script original.
    kBoltz = physconst('Boltzmann');
    NF = 10^(simParameters.RxNoiseFigure / 10);
    Teq = simParameters.RxAntTemperature + 290 * (NF - 1);
    N0 = sqrt(kBoltz * waveformInfo.SampleRate * Teq / 2.0);
    fftOccupancy = 12 * simParameters.Carrier.NSizeGrid / waveformInfo.Nfft;

    %% Simulacion
    inicio_mueve = true;
    step = 0;
    num_autos = 500;

    bler_movil = cell(1,num_autos);
    bler_cen = cell(1,num_autos);
    simThroughput_vehiculos_Movil = cell(1, num_autos);
    maxThroughput_vehiculos_Movil = cell(1,num_autos);
    simThroughput_vehiculos_Cen = cell(1, num_autos);
    maxThroughput_vehiculos_Cen = cell(1,num_autos);
    pos3D_history_vehiculos = cell(1, num_autos);
    throughput_vehiculos_Predefinido = cell(num_autos, 1);
    throughput_vehiculos_Fijo = cell(num_autos, 1);
    throughput_vehiculos_Movil = cell(num_autos, 1);
    throughput_vehiculos_Cen = cell(num_autos, 1);

    for i = 1:num_autos
        throughput_vehiculos_Movil{i} = [];
        throughput_vehiculos_Cen{i} = [];
        bler_movil{i} = [];
        bler_cen{i} =[];
        simThroughput_vehiculos_Movil{i} = [];
        maxThroughput_vehiculos_Movil{i} = [];
        simThroughput_vehiculos_Cen{i} = [];
        maxThroughput_vehiculos_Cen{i} = [];
        pos3D_history_vehiculos{i} = [];
    end

    total_longitud_km = 0;
    total_carriles = 0;
    for i = 1:num_edges
        edgeID = edges{i};
        num_carriles = traci.edge.getLaneNumber(edgeID);
        total_carriles = total_carriles + num_carriles;
        longitud_edge = 0;
        for lane_idx = 0:num_carriles-1
            laneID = [edgeID, '_', num2str(lane_idx)];
            longitud_edge = longitud_edge + traci.lane.getLength(laneID) / 1000;
        end
        total_longitud_km = total_longitud_km + longitud_edge;
    end

    while step < tiempo_simulacion+1
        traci.simulationStep();
        step = step + 1;
        disp(['Step actual: ', num2str(step)]) %[output:0598fee3] %[output:01aae196]
        if step < 51
            continue;
        end

        carsInSim = traci.vehicle.getIDList();
        if isempty(carsInSim) && step == 1
            vehicleID = ['Auto_extra_', num2str(step), '_', num2str(j)]; %#ok<NODEF>
            routes = {'r_0', 'r_1', 'r_2'};
            randomRouteIndex = randi(length(routes));
            routeID = routes{randomRouteIndex};
            depart = '0';
            traci.vehicle.add(vehicleID, routeID, 'Auto', depart, 'first', '10');
        end

        total_vehiculos = 0;
        for i = 1:num_edges
            edgeID = edges{i};
            num_vehiculos = traci.edge.getLastStepVehicleNumber(edgeID);
            total_vehiculos = total_vehiculos + num_vehiculos;
        end
        densidad_vehicular_total = total_vehiculos / total_longitud_km;
        densidades_totales = [densidades_totales, densidad_vehicular_total];

        if inicio_mueve
            if ismember(poiID_Movil, traci.poi.getIDList())
                pos2D_dron_Movil = traci.poi.getPosition(poiID_Movil);
                posX_dron_Movil = pos2D_dron_Movil(1);
                posY_dron_Movil = pos2D_dron_Movil(2);
                pos3D_history_Movil = [pos3D_history_Movil; posX_dron_Movil, posY_dron_Movil, simParameters.TxHeight];
            end
            if ismember(poiID_Cen, traci.poi.getIDList())
                pos2D_dron_Cen = traci.poi.getPosition(poiID_Cen);
                posX_dron_Cen = pos2D_dron_Cen(1);
                posY_dron_Cen = pos2D_dron_Cen(2);
                pos3D_history_Cen = [pos3D_history_Cen; posX_dron_Cen, posY_dron_Cen, simParameters.TxHeight];
            end

            carsInSim = traci.vehicle.getIDList();
            num_vehiculos_presentes = length(carsInSim);
            rxPositions = zeros(3, num_vehiculos_presentes);
            for i = 1:num_vehiculos_presentes
                vehicleID = carsInSim{i};
                if ismember(vehicleID, carsInSim)
                    pos2D = traci.vehicle.getPosition(vehicleID);
                    rxPositions(:, i) = [pos2D(1); pos2D(2); simParameters.RxHeight];
                    if isempty(pos3D_history_vehiculos{i})
                        pos3D_history_vehiculos{i} = [pos2D(1), pos2D(2), simParameters.RxHeight];
                    else
                        pos3D_history_vehiculos{i} = [pos3D_history_vehiculos{i}; pos2D(1), pos2D(2), simParameters.RxHeight];
                    end
                else
                    rxPositions(:, i) = NaN;
                end
            end

            %% ---------------- Enlace del dron movil (UAV1) ----------------
            if ismember(poiID_Movil, traci.poi.getIDList())
                stepSNRs_Movil = NaN(1, size(rxPositions, 2));
                losFlags_Movil = false(1, size(rxPositions, 2));  % NUEVO

                for i = 1:size(rxPositions, 2)
                    if all(~isnan(rxPositions(:, i)))
                        txPosition = [posX_dron_Movil; posY_dron_Movil; simParameters.TxHeight];
                        rxPosition = rxPositions(:, i);

                        % NUEVO: LOS/NLOS por enlace (obstaculo + modelo
                        % probabilistico), en vez de simParameters.LOS global.
                        [LOS_i, pathLoss] = evaluatePropagation(txPosition, rxPosition, simParameters, 'sampled');

                        if LOS_i
                            sigmaShadow = simParameters.ShadowSigmaLOS;
                        else
                            sigmaShadow = simParameters.ShadowSigmaNLOS;
                        end
                        [shadowdB, shadowState_Movil] = updateShadowFading(carsInSim{i}, rxPosition, ...
                            sigmaShadow, simParameters.CorrDistance, shadowState_Movil);
                        pathLoss = pathLoss + shadowdB;

                        losFlags_Movil(i) = LOS_i;
                        simParameters.SNRIn = (simParameters.TxPower - 30) - pathLoss - 10 * log10(fftOccupancy) - 10 * log10(2 * N0^2);
                        stepSNRs_Movil(i) = simParameters.SNRIn;
                    end
                end

                if size(SNRs_Movil, 2) == size(stepSNRs_Movil, 2)
                    SNRs_Movil = [SNRs_Movil; stepSNRs_Movil];
                else
                    diff_size = size(SNRs_Movil, 2) - size(stepSNRs_Movil, 2);
                    if diff_size > 0
                        stepSNRs_Movil = padarray(stepSNRs_Movil, [0, diff_size], NaN, 'post');
                    else
                        SNRs_Movil = padarray(SNRs_Movil, [0, -diff_size], NaN, 'post');
                    end
                    SNRs_Movil = [SNRs_Movil; stepSNRs_Movil];
                end
                promedioSNR_Movil = [promedioSNR_Movil, nanmean(stepSNRs_Movil)];

                parfor i = 1:length(carsInSim) %[output:09cc15ef]
                    % CORREGIDO: se elimina el chequeo erroneo
                    % `ismember(vehicleID, carsInSim)` (vehicleID quedaba
                    % con el valor residual del ultimo for-loop serial y
                    % era siempre verdadero, sin relacion con i).
                    if ~isnan(stepSNRs_Movil(i))
                        SNRdB = stepSNRs_Movil(i);
                        rng('shuffle');
                        carrier = simParameters.Carrier;
                        pdsch = simParameters.PDSCH;
                        pdschextra = simParameters.PDSCHExtension;
                        decodeDLSCHLocal = decodeDLSCH;
                        decodeDLSCHLocal.reset();
                        pathFilters = [];
                        NSlots = simParameters.NFrames * carrier.SlotsPerFrame;
                        trBlk = [];

                        % NUEVO: canal de fading por enlace (LOS -> CDL-D,
                        % NLOS -> CDL-A) en vez de un canal global unico.
                        if losFlags_Movil(i)
                            profileName = simParameters.DelayProfileLOS;
                        else
                            profileName = simParameters.DelayProfileNLOS;
                        end
                        [channelLocal, maxChDelayLocal] = buildLocalChannel(profileName, simParameters, waveformInfo);

                        estChannelGridAnts = getInitialChannelEstimate(carrier, simParameters.NTxAnts, channelLocal, simParameters.DataType);
                        newWtx = hSVDPrecoders(carrier, pdsch, estChannelGridAnts, pdschextra.PRGBundleSize);
                        offset = 0;
                        simThroughput = 0;
                        maxThroughput = 0;
                        err_movil = 0;
                        harqSequence = 0:pdschextra.NHARQProcesses-1;
                        harqEntity = HARQEntity(harqSequence, rvSeq, pdsch.NumCodewords);

                        for nslot = 0:NSlots-1
                            carrier.NSlot = nslot;
                            [pdschIndices, pdschIndicesInfo] = nrPDSCHIndices(carrier, pdsch);
                            trBlkSizes = nrTBS(pdsch.Modulation, pdsch.NumLayers, numel(pdsch.PRBSet), pdschIndicesInfo.NREPerPRB, pdschextra.TargetCodeRate, pdschextra.XOverhead);

                            for cwIdx = 1:pdsch.NumCodewords
                                if harqEntity.NewData(cwIdx)
                                    trBlk = randi([0 1], trBlkSizes(cwIdx), 1);
                                    setTransportBlock(encodeDLSCH, trBlk, cwIdx-1, harqEntity.HARQProcessID);
                                    if harqEntity.SequenceTimeout(cwIdx)
                                        resetSoftBuffer(decodeDLSCHLocal, cwIdx-1, harqEntity.HARQProcessID);
                                    end
                                end
                            end

                            codedTrBlocks = encodeDLSCH(pdsch.Modulation, pdsch.NumLayers, pdschIndicesInfo.G, harqEntity.RedundancyVersion, harqEntity.HARQProcessID);
                            wtx = newWtx;
                            pdschGrid = nrResourceGrid(carrier, simParameters.NTxAnts, 'OutputDataType', simParameters.DataType);
                            pdschSymbols = nrPDSCH(carrier, pdsch, codedTrBlocks);
                            [pdschAntSymbols, pdschAntIndices] = nrPDSCHPrecode(carrier, pdschSymbols, pdschIndices, wtx);
                            pdschGrid(pdschAntIndices) = pdschAntSymbols;
                            dmrsSymbols = nrPDSCHDMRS(carrier, pdsch);
                            dmrsIndices = nrPDSCHDMRSIndices(carrier, pdsch);
                            [dmrsAntSymbols, dmrsAntIndices] = nrPDSCHPrecode(carrier, dmrsSymbols, dmrsIndices, wtx);
                            pdschGrid(dmrsAntIndices) = dmrsAntSymbols;
                            ptrsSymbols = nrPDSCHPTRS(carrier, pdsch);
                            ptrsIndices = nrPDSCHPTRSIndices(carrier, pdsch);
                            [ptrsAntSymbols, ptrsAntIndices] = nrPDSCHPrecode(carrier, ptrsSymbols, ptrsIndices, wtx);
                            pdschGrid(ptrsAntIndices) = ptrsAntSymbols;
                            txWaveform = nrOFDMModulate(carrier, pdschGrid);
                            txWaveform = [txWaveform; zeros(maxChDelayLocal, size(txWaveform, 2))];

                            [rxWaveform, pathGains, sampleTimes] = channelLocal(txWaveform);
                            SNR = 10^(SNRdB / 10);
                            N0local = 1 / sqrt(simParameters.NRxAnts * double(waveformInfo.Nfft) * SNR);
                            noise = N0local * randn(size(rxWaveform), "like", rxWaveform);
                            rxWaveform = rxWaveform + noise;

                            if simParameters.PerfectChannelEstimator
                                pathFilters = getPathFilters(channelLocal);
                                [offset, mag] = nrPerfectTimingEstimate(pathGains, pathFilters);
                            else
                                [t, mag] = nrTimingEstimate(carrier, rxWaveform, dmrsIndices, dmrsSymbols);
                                offset = hSkipWeakTimingOffset(offset, t, mag);
                                if offset > maxChDelayLocal
                                    warning(['Estimated timing offset (%d) is greater than the maximum channel delay (%d).' ...
                                        ' This will result in a decoding failure. This may be caused by low SNR,' ...
                                        ' or not enough DM-RS symbols to synchronize successfully.'], offset, maxChDelayLocal);
                                end
                            end

                            rxWaveform = rxWaveform(1 + offset:end, :);
                            rxGrid = nrOFDMDemodulate(carrier, rxWaveform);
                            [K, L, R] = size(rxGrid);
                            if L < carrier.SymbolsPerSlot
                                rxGrid = cat(2, rxGrid, zeros(K, carrier.SymbolsPerSlot - L, R));
                            end

                            if simParameters.PerfectChannelEstimator
                                estChannelGridAnts = nrPerfectChannelEstimate(carrier, pathGains, pathFilters, offset, sampleTimes);
                                noiseGrid = nrOFDMDemodulate(carrier, noise(1 + offset:end, :));
                                noiseEst = var(noiseGrid(:));
                                [pdschRx, pdschHest, ~, pdschHestIndices] = nrExtractResources(pdschIndices, rxGrid, estChannelGridAnts);
                                pdschHest = nrPDSCHPrecode(carrier, pdschHest, pdschHestIndices, permute(wtx, [2 1 3]));
                            else
                                [estChannelGridPorts, noiseEst] = hSubbandChannelEstimate(carrier, rxGrid, dmrsIndices, dmrsSymbols, pdschextra.PRGBundleSize, 'CDMLengths', pdsch.DMRS.CDMLengths);
                                noiseEst = mean(noiseEst, 'all');
                                [pdschRx, pdschHest] = nrExtractResources(pdschIndices, rxGrid, estChannelGridPorts);
                                estChannelGridAnts = precodeChannelEstimate(carrier, estChannelGridPorts, conj(wtx));
                            end

                            [pdschEq, csi] = nrEqualizeMMSE(pdschRx, pdschHest, noiseEst);

                            if ~isempty(ptrsIndices)
                                tempGrid = nrResourceGrid(carrier, pdsch.NumLayers);
                                [ptrsRx, ptrsHest, ~, ~, ptrsHestIndices, ptrsLayerIndices] = nrExtractResources(ptrsIndices, rxGrid, estChannelGridAnts, tempGrid);
                                ptrsHest = nrPDSCHPrecode(carrier, ptrsHest, ptrsHestIndices, permute(wtx, [2 1 3]));
                                ptrsEq = nrEqualizeMMSE(ptrsRx, ptrsHest, noiseEst);
                                tempGrid(ptrsLayerIndices) = ptrsEq;
                                cpe = nrChannelEstimate(tempGrid, ptrsIndices, ptrsSymbols);
                                cpe = angle(sum(cpe, [1 3 4]));
                                tempGrid(pdschIndices) = pdschEq;
                                symLoc = pdschIndicesInfo.PTRSSymbolSet(1) + 1:pdschIndicesInfo.PTRSSymbolSet(end) + 1;
                                tempGrid(:, symLoc, :) = tempGrid(:, symLoc, :) .* exp(-1i * cpe(symLoc));
                                pdschEq = tempGrid(pdschIndices);
                            end

                            [dlschLLRs, rxSymbols] = nrPDSCHDecode(carrier, pdsch, pdschEq, noiseEst);

                            if simParameters.DisplayDiagnostics
                                plotLayerEVM(NSlots, nslot, pdsch, size(pdschGrid), pdschIndices, pdschSymbols, pdschEq);
                            end

                            csi = nrLayerDemap(csi);
                            for cwIdx = 1:pdsch.NumCodewords
                                Qm = length(dlschLLRs{cwIdx}) / length(rxSymbols{cwIdx});
                                csi{cwIdx} = repmat(csi{cwIdx}.', Qm, 1);
                                dlschLLRs{cwIdx} = dlschLLRs{cwIdx} .* csi{cwIdx}(:);
                            end

                            decodeDLSCHLocal.TransportBlockLength = trBlkSizes;
                            [decbits, blkerr] = decodeDLSCHLocal(dlschLLRs, pdsch.Modulation, pdsch.NumLayers, harqEntity.RedundancyVersion, harqEntity.HARQProcessID);
                            simThroughput = simThroughput + sum(~blkerr .* trBlkSizes);
                            maxThroughput = maxThroughput + sum(trBlkSizes);
                            err_movil = err_movil + (~isequal(decbits,trBlk));
                            procstatus = updateAndAdvance(harqEntity, blkerr, trBlkSizes, pdschIndicesInfo.G); %#ok<NASGU>
                            newWtx = hSVDPrecoders(carrier, pdsch, estChannelGridAnts, pdschextra.PRGBundleSize);
                        end

                        throughputPercentage = simThroughput * 100 / maxThroughput;
                        throughput_vehiculos_Movil{i} = [throughput_vehiculos_Movil{i}; throughputPercentage];
                        simThroughput_vehiculos_Movil{i} = [simThroughput_vehiculos_Movil{i}; simThroughput];
                        maxThroughput_vehiculos_Movil{i} = [maxThroughput_vehiculos_Movil{i}; maxThroughput];
                        bler_movil1 = err_movil/NSlots;
                        bler_movil{i} = [bler_movil{i}; bler_movil1];
                    else
                        throughput_vehiculos_Movil{i} = [throughput_vehiculos_Movil{i}; NaN];
                        maxThroughput_vehiculos_Movil{i} = [maxThroughput_vehiculos_Movil{i}; NaN];
                        simThroughput_vehiculos_Movil{i} = [simThroughput_vehiculos_Movil{i}; NaN];
                        bler_movil{i} = [bler_movil{i}; NaN];
                    end
                end
            end

            %% ---------------- Enlace del dron centroide (UAV4) ----------------
            if ismember(poiID_Cen, traci.poi.getIDList())
                stepSNRs_Cen = NaN(1, size(rxPositions, 2));
                losFlags_Cen = false(1, size(rxPositions, 2));  % NUEVO

                for i = 1:size(rxPositions, 2)
                    if all(~isnan(rxPositions(:, i)))
                        txPosition = [posX_dron_Cen; posY_dron_Cen; simParameters.TxHeight];
                        rxPosition = rxPositions(:, i);

                        [LOS_i, pathLoss] = evaluatePropagation(txPosition, rxPosition, simParameters, 'sampled');

                        if LOS_i
                            sigmaShadow = simParameters.ShadowSigmaLOS;
                        else
                            sigmaShadow = simParameters.ShadowSigmaNLOS;
                        end
                        [shadowdB, shadowState_Cen] = updateShadowFading(carsInSim{i}, rxPosition, ...
                            sigmaShadow, simParameters.CorrDistance, shadowState_Cen);
                        pathLoss = pathLoss + shadowdB;

                        losFlags_Cen(i) = LOS_i;
                        simParameters.SNRIn = (simParameters.TxPower - 30) - pathLoss - 10 * log10(fftOccupancy) - 10 * log10(2 * N0^2);
                        stepSNRs_Cen(i) = simParameters.SNRIn;
                    end
                end

                if size(SNRs_Cen, 2) == size(stepSNRs_Cen, 2)
                    SNRs_Cen = [SNRs_Cen; stepSNRs_Cen];
                else
                    diff_size = size(SNRs_Cen, 2) - size(stepSNRs_Cen, 2);
                    if diff_size > 0
                        stepSNRs_Cen = padarray(stepSNRs_Cen, [0, diff_size], NaN, 'post');
                    else
                        SNRs_Cen = padarray(SNRs_Cen, [0, -diff_size], NaN, 'post');
                    end
                    SNRs_Cen = [SNRs_Cen; stepSNRs_Cen];
                end
                promedioSNR_Cen = [promedioSNR_Cen, nanmean(stepSNRs_Cen)];

                parfor i = 1:length(carsInSim)
                    if ~isnan(stepSNRs_Cen(i))
                        SNRdB = stepSNRs_Cen(i);
                        rng('shuffle');
                        carrier = simParameters.Carrier;
                        pdsch = simParameters.PDSCH;
                        pdschextra = simParameters.PDSCHExtension;
                        decodeDLSCHLocal = decodeDLSCH;
                        decodeDLSCHLocal.reset();
                        pathFilters = [];
                        NSlots = simParameters.NFrames * carrier.SlotsPerFrame;
                        trBlk = [];

                        if losFlags_Cen(i)
                            profileName = simParameters.DelayProfileLOS;
                        else
                            profileName = simParameters.DelayProfileNLOS;
                        end
                        [channelLocal, maxChDelayLocal] = buildLocalChannel(profileName, simParameters, waveformInfo);

                        estChannelGridAnts = getInitialChannelEstimate(carrier, simParameters.NTxAnts, channelLocal, simParameters.DataType);
                        newWtx = hSVDPrecoders(carrier, pdsch, estChannelGridAnts, pdschextra.PRGBundleSize);
                        offset = 0;
                        simThroughput = 0;
                        maxThroughput = 0;
                        err_Cen = 0;
                        harqSequence = 0:pdschextra.NHARQProcesses-1;
                        harqEntity = HARQEntity(harqSequence, rvSeq, pdsch.NumCodewords);

                        for nslot = 0:NSlots-1
                            carrier.NSlot = nslot;
                            [pdschIndices, pdschIndicesInfo] = nrPDSCHIndices(carrier, pdsch);
                            trBlkSizes = nrTBS(pdsch.Modulation, pdsch.NumLayers, numel(pdsch.PRBSet), pdschIndicesInfo.NREPerPRB, pdschextra.TargetCodeRate, pdschextra.XOverhead);

                            for cwIdx = 1:pdsch.NumCodewords
                                if harqEntity.NewData(cwIdx)
                                    trBlk = randi([0 1], trBlkSizes(cwIdx), 1);
                                    setTransportBlock(encodeDLSCH, trBlk, cwIdx-1, harqEntity.HARQProcessID);
                                    if harqEntity.SequenceTimeout(cwIdx)
                                        resetSoftBuffer(decodeDLSCHLocal, cwIdx-1, harqEntity.HARQProcessID);
                                    end
                                end
                            end

                            codedTrBlocks = encodeDLSCH(pdsch.Modulation, pdsch.NumLayers, pdschIndicesInfo.G, harqEntity.RedundancyVersion, harqEntity.HARQProcessID);
                            wtx = newWtx;
                            pdschGrid = nrResourceGrid(carrier, simParameters.NTxAnts, 'OutputDataType', simParameters.DataType);
                            pdschSymbols = nrPDSCH(carrier, pdsch, codedTrBlocks);
                            [pdschAntSymbols, pdschAntIndices] = nrPDSCHPrecode(carrier, pdschSymbols, pdschIndices, wtx);
                            pdschGrid(pdschAntIndices) = pdschAntSymbols;
                            dmrsSymbols = nrPDSCHDMRS(carrier, pdsch);
                            dmrsIndices = nrPDSCHDMRSIndices(carrier, pdsch);
                            [dmrsAntSymbols, dmrsAntIndices] = nrPDSCHPrecode(carrier, dmrsSymbols, dmrsIndices, wtx);
                            pdschGrid(dmrsAntIndices) = dmrsAntSymbols;
                            ptrsSymbols = nrPDSCHPTRS(carrier, pdsch);
                            ptrsIndices = nrPDSCHPTRSIndices(carrier, pdsch);
                            [ptrsAntSymbols, ptrsAntIndices] = nrPDSCHPrecode(carrier, ptrsSymbols, ptrsIndices, wtx);
                            pdschGrid(ptrsAntIndices) = ptrsAntSymbols;
                            txWaveform = nrOFDMModulate(carrier, pdschGrid);
                            txWaveform = [txWaveform; zeros(maxChDelayLocal, size(txWaveform, 2))];

                            [rxWaveform, pathGains, sampleTimes] = channelLocal(txWaveform);
                            SNR = 10^(SNRdB / 10);
                            N0local = 1 / sqrt(simParameters.NRxAnts * double(waveformInfo.Nfft) * SNR);
                            noise = N0local * randn(size(rxWaveform), "like", rxWaveform);
                            rxWaveform = rxWaveform + noise;

                            if simParameters.PerfectChannelEstimator
                                pathFilters = getPathFilters(channelLocal);
                                [offset, mag] = nrPerfectTimingEstimate(pathGains, pathFilters);
                            else
                                [t, mag] = nrTimingEstimate(carrier, rxWaveform, dmrsIndices, dmrsSymbols);
                                offset = hSkipWeakTimingOffset(offset, t, mag);
                                if offset > maxChDelayLocal
                                    warning(['Estimated timing offset (%d) is greater than the maximum channel delay (%d).' ...
                                        ' This will result in a decoding failure. This may be caused by low SNR,' ...
                                        ' or not enough DM-RS symbols to synchronize successfully.'], offset, maxChDelayLocal);
                                end
                            end

                            rxWaveform = rxWaveform(1 + offset:end, :);
                            rxGrid = nrOFDMDemodulate(carrier, rxWaveform);
                            [K, L, R] = size(rxGrid);
                            if L < carrier.SymbolsPerSlot
                                rxGrid = cat(2, rxGrid, zeros(K, carrier.SymbolsPerSlot - L, R));
                            end

                            if simParameters.PerfectChannelEstimator
                                estChannelGridAnts = nrPerfectChannelEstimate(carrier, pathGains, pathFilters, offset, sampleTimes);
                                noiseGrid = nrOFDMDemodulate(carrier, noise(1 + offset:end, :));
                                noiseEst = var(noiseGrid(:));
                                [pdschRx, pdschHest, ~, pdschHestIndices] = nrExtractResources(pdschIndices, rxGrid, estChannelGridAnts);
                                pdschHest = nrPDSCHPrecode(carrier, pdschHest, pdschHestIndices, permute(wtx, [2 1 3]));
                            else
                                [estChannelGridPorts, noiseEst] = hSubbandChannelEstimate(carrier, rxGrid, dmrsIndices, dmrsSymbols, pdschextra.PRGBundleSize, 'CDMLengths', pdsch.DMRS.CDMLengths);
                                noiseEst = mean(noiseEst, 'all');
                                [pdschRx, pdschHest] = nrExtractResources(pdschIndices, rxGrid, estChannelGridPorts);
                                estChannelGridAnts = precodeChannelEstimate(carrier, estChannelGridPorts, conj(wtx));
                            end

                            [pdschEq, csi] = nrEqualizeMMSE(pdschRx, pdschHest, noiseEst);

                            if ~isempty(ptrsIndices)
                                tempGrid = nrResourceGrid(carrier, pdsch.NumLayers);
                                [ptrsRx, ptrsHest, ~, ~, ptrsHestIndices, ptrsLayerIndices] = nrExtractResources(ptrsIndices, rxGrid, estChannelGridAnts, tempGrid);
                                ptrsHest = nrPDSCHPrecode(carrier, ptrsHest, ptrsHestIndices, permute(wtx, [2 1 3]));
                                ptrsEq = nrEqualizeMMSE(ptrsRx, ptrsHest, noiseEst);
                                tempGrid(ptrsLayerIndices) = ptrsEq;
                                cpe = nrChannelEstimate(tempGrid, ptrsIndices, ptrsSymbols);
                                cpe = angle(sum(cpe, [1 3 4]));
                                tempGrid(pdschIndices) = pdschEq;
                                symLoc = pdschIndicesInfo.PTRSSymbolSet(1) + 1:pdschIndicesInfo.PTRSSymbolSet(end) + 1;
                                tempGrid(:, symLoc, :) = tempGrid(:, symLoc, :) .* exp(-1i * cpe(symLoc));
                                pdschEq = tempGrid(pdschIndices);
                            end

                            [dlschLLRs, rxSymbols] = nrPDSCHDecode(carrier, pdsch, pdschEq, noiseEst);

                            if simParameters.DisplayDiagnostics
                                plotLayerEVM(NSlots, nslot, pdsch, size(pdschGrid), pdschIndices, pdschSymbols, pdschEq);
                            end

                            csi = nrLayerDemap(csi);
                            for cwIdx = 1:pdsch.NumCodewords
                                Qm = length(dlschLLRs{cwIdx}) / length(rxSymbols{cwIdx});
                                csi{cwIdx} = repmat(csi{cwIdx}.', Qm, 1);
                                dlschLLRs{cwIdx} = dlschLLRs{cwIdx} .* csi{cwIdx}(:);
                            end

                            decodeDLSCHLocal.TransportBlockLength = trBlkSizes;
                            [decbits, blkerr] = decodeDLSCHLocal(dlschLLRs, pdsch.Modulation, pdsch.NumLayers, harqEntity.RedundancyVersion, harqEntity.HARQProcessID);
                            simThroughput = simThroughput + sum(~blkerr .* trBlkSizes);
                            maxThroughput = maxThroughput + sum(trBlkSizes);
                            err_Cen = err_Cen + (~isequal(decbits,trBlk));
                            procstatus = updateAndAdvance(harqEntity, blkerr, trBlkSizes, pdschIndicesInfo.G); %#ok<NASGU>
                            newWtx = hSVDPrecoders(carrier, pdsch, estChannelGridAnts, pdschextra.PRGBundleSize);
                        end

                        throughputPercentage = simThroughput * 100 / maxThroughput;
                        throughput_vehiculos_Cen{i} = [throughput_vehiculos_Cen{i}; throughputPercentage];
                        simThroughput_vehiculos_Cen{i} = [simThroughput_vehiculos_Cen{i}; simThroughput];
                        maxThroughput_vehiculos_Cen{i} = [maxThroughput_vehiculos_Cen{i}; maxThroughput];
                        bler_cen1 = err_Cen/NSlots;
                        bler_cen{i} = [bler_cen{i}; bler_cen1];
                    else
                        throughput_vehiculos_Cen{i} = [throughput_vehiculos_Cen{i}; NaN];
                        maxThroughput_vehiculos_Cen{i} = [maxThroughput_vehiculos_Cen{i}; NaN];
                        simThroughput_vehiculos_Cen{i} = [simThroughput_vehiculos_Cen{i}; NaN];
                        bler_cen{i} = [bler_cen{i}; NaN];
                    end
                end
            end

            %% Movimiento del dron Centroide (baseline UAV4, sin cambios de logica)
            valid = ~isnan(rxPositions(1,:)) & ~isnan(rxPositions(2,:));
            if any(valid)
                centroidX = mean(rxPositions(1,valid));
                centroidY = mean(rxPositions(2,valid));
            else
                centroidX = posX_dron_Cen;
                centroidY = posY_dron_Cen;
            end

            num_aceleraciones_cen = 5;
            posible_dir_cen = 36;
            resolucion_ang_cen = 2*pi/posible_dir_cen;
            ang_cen = 0:resolucion_ang_cen:(2*pi - resolucion_ang_cen);
            posX2_cen = zeros(posible_dir_cen, num_aceleraciones_cen);
            posY2_cen = zeros(posible_dir_cen, num_aceleraciones_cen);
            score_cen = -inf(posible_dir_cen, num_aceleraciones_cen);
            acel_cen = linspace(-acel_max, acel_max, num_aceleraciones_cen);

            for k = 1:posible_dir_cen
                for a = 1:num_aceleraciones_cen
                    Vel_nueva_cen = min(Vel_max, Vel_dron_Cen + acel_cen(a)*tiempo);
                    disX = Vel_nueva_cen*tiempo*cos(ang_cen(k)) + 0.5*acel_cen(a)*tiempo^2*cos(ang_cen(k));
                    disY = Vel_nueva_cen*tiempo*sin(ang_cen(k)) + 0.5*acel_cen(a)*tiempo^2*sin(ang_cen(k));
                    posX2_cen(k,a) = posX_dron_Cen + disX;
                    posY2_cen(k,a) = posY_dron_Cen + disY;
                    dist = sqrt((posX2_cen(k,a) - centroidX)^2 + (posY2_cen(k,a) - centroidY)^2);
                    score_cen(k,a) = -dist;
                end
            end

            [~, idxC] = max(score_cen(:));
            [bestDirC, bestAccC] = ind2sub(size(score_cen), idxC);
            Vel_dron_Cen = min(Vel_max, Vel_dron_Cen + acel_cen(bestAccC)*tiempo);
            nueva_posX_cen = posX2_cen(bestDirC, bestAccC);
            nueva_posY_cen = posY2_cen(bestDirC, bestAccC);
            traci.poi.setPosition(poiID_Cen, nueva_posX_cen, nueva_posY_cen);
            posX_dron_Cen = nueva_posX_cen;
            posY_dron_Cen = nueva_posY_cen;

            %% Movimiento del dron movil (UAV1) - objetivo seleccionable
            num_aceleraciones = 5;
            posible_dir = 36;
            resolucion_ang = 2 * pi / posible_dir;
            angulo = 0:resolucion_ang:(2 * pi - resolucion_ang);
            posX2_movil = zeros(posible_dir, num_aceleraciones);
            posY2_movil = zeros(posible_dir, num_aceleraciones);
            promedio_SNRs = -inf(posible_dir, num_aceleraciones);
            aceleraciones = linspace(-acel_max, acel_max, num_aceleraciones);

            % NUEVO: pesos de prioridad de usuario (heterogeneidad de
            % requisitos), usados solo si simParameters.UAV1Objective = 'weighted'
            pesos_vehiculos = zeros(1, length(carsInSim));
            for j = 1:length(carsInSim)
                pesos_vehiculos(j) = vehiclePriorityWeight(carsInSim{j});
            end

            for k = 1:posible_dir
                for a = 1:num_aceleraciones
                    Vel_nueva = min(Vel_max, Vel_dron + aceleraciones(a) * tiempo);
                    disX = Vel_nueva * tiempo * cos(angulo(k)) + 0.5 * aceleraciones(a) * tiempo^2 * cos(angulo(k));
                    disY = Vel_nueva * tiempo * sin(angulo(k)) + 0.5 * aceleraciones(a) * tiempo^2 * sin(angulo(k));
                    posX2_movil(k, a) = posX_dron_Movil + disX;
                    posY2_movil(k, a) = posY_dron_Movil + disY;

                    % NUEVO: SNR candidata por vehiculo, usando el modelo
                    % hibrido en modo 'expected' (path loss LOS/NLOS
                    % combinado segun probabilidad de LOS, determinista,
                    % SIN sombreado ni muestreo aleatorio) para que la
                    % busqueda de trayectoria sea suave y reproducible.
                    snr_vec = NaN(1, length(carsInSim));
                    for j = 1:length(carsInSim)
                        if ~isnan(rxPositions(1, j))
                            txPositionCand = [posX2_movil(k, a); posY2_movil(k, a); simParameters.TxHeight];
                            rxPosition = rxPositions(:, j);
                            [~, pathLossCand] = evaluatePropagation(txPositionCand, rxPosition, simParameters, 'expected');
                            snr_vec(j) = (simParameters.TxPower - 30) - pathLossCand - 10 * log10(fftOccupancy) - 10 * log10(2 * N0^2);
                        end
                    end

                    validIdx = ~isnan(snr_vec);
                    if any(validIdx)
                        switch simParameters.UAV1Objective
                            case 'maxmin'
                                promedio_SNRs(k, a) = min(snr_vec(validIdx));
                            case 'weighted'
                                w = pesos_vehiculos(validIdx);
                                promedio_SNRs(k, a) = sum(w .* snr_vec(validIdx)) / sum(w);
                            otherwise % 'mean'
                                promedio_SNRs(k, a) = mean(snr_vec(validIdx));
                        end
                    end
                end
            end
        end

        [~, idx] = max(promedio_SNRs(:));
        [mejor_direccion, mejor_aceleracion_idx] = ind2sub(size(promedio_SNRs), idx);
        Vel_dron = min(Vel_max, Vel_dron + aceleraciones(mejor_aceleracion_idx) * tiempo);
        traci.poi.setPosition(poiID_Movil, posX2_movil(mejor_direccion, mejor_aceleracion_idx), posY2_movil(mejor_direccion, mejor_aceleracion_idx));

        % CORREGIDO: se actualizan AMBAS coordenadas del estado local del
        % dron movil (el original solo actualizaba posY_dron_Movil).
        posX_dron_Movil = posX2_movil(mejor_direccion, mejor_aceleracion_idx);
        posY_dron_Movil = posY2_movil(mejor_direccion, mejor_aceleracion_idx);
    end
end %[output:group:0640207d]

traci.close();

%% Ajustar la longitud de las matrices de datos para cada vehiculo
maxSteps = length(promedioSNR_Movil);
fsize = 10;
lsize = 2;
steps = (0:maxSteps-1)/divisor;
steps_movil = (0:maxSteps-1)/divisor;

maxRows_SNR = max([size(SNRs_Movil, 1)]);
maxCols = max([size(SNRs_Movil, 2)]);
SNRs_Movil = padWithNaN(SNRs_Movil, [maxRows_SNR, maxCols]);
SNRs_Cen = padWithNaN(SNRs_Cen, [maxRows_SNR, maxCols]);

maxSteps = max([cellfun(@(x) size(x, 1), simThroughput_vehiculos_Movil), ...
    cellfun(@(x) size(x, 1), simThroughput_vehiculos_Cen)]);

for i = 1:length(simThroughput_vehiculos_Movil)
    simThroughput_vehiculos_Movil{i} = padarray(simThroughput_vehiculos_Movil{i}, ...
        [maxSteps - size(simThroughput_vehiculos_Movil{i}, 1), 0], NaN, 'post');
    simThroughput_vehiculos_Cen{i} = padarray(simThroughput_vehiculos_Cen{i}, ...
        [maxSteps - size(simThroughput_vehiculos_Cen{i}, 1), 0], NaN, 'post');
    maxThroughput_vehiculos_Movil{i} = padarray(maxThroughput_vehiculos_Movil{i}, ...
        [maxSteps - size(maxThroughput_vehiculos_Movil{i}, 1), 0], NaN, 'post');
    maxThroughput_vehiculos_Cen{i} = padarray(maxThroughput_vehiculos_Cen{i}, ...
        [maxSteps - size(maxThroughput_vehiculos_Cen{i}, 1), 0], NaN, 'post');
end

simThroughput_vehiculos_Movil = simThroughput_vehiculos_Movil(~cellfun('isempty', simThroughput_vehiculos_Movil));
simThroughput_vehiculos_Cen = simThroughput_vehiculos_Cen(~cellfun('isempty', simThroughput_vehiculos_Cen));

simThroughput_vehiculos_Movil2 = cell2mat(simThroughput_vehiculos_Movil);
simThroughput_vehiculos_Cen2 = cell2mat(simThroughput_vehiculos_Cen);

maxRows_bler = max([cellfun(@(x) size(x, 1), bler_movil), ...
    cellfun(@(x) size(x, 1), bler_cen)]);

for i = 1:length(bler_movil)
    bler_movil{i} = padarray(bler_movil{i}, ...
        [maxRows_bler - size(bler_movil{i}, 1), 0], NaN, 'post');
end
for i = 1:length(bler_cen)
    bler_cen{i} = padarray(bler_cen{i}, ...
        [maxRows_bler - size(bler_cen{i}, 1), 0], NaN, 'post');
end

bler_movil2 = cell2mat(bler_movil);
bler_cen2 = cell2mat(bler_cen);

promedioThroughput_Movil = nanmean(simThroughput_vehiculos_Movil2, 2);
promedioBler_Movil = nanmean(bler_movil2, 2);
promedioThroughput_Cen = nanmean(simThroughput_vehiculos_Cen2, 2);
promedioBler_Cen = nanmean(bler_cen2, 2);

promedioThroughput_Movil = 1e-6*promedioThroughput_Movil/(simParameters.NFrames*10e-3);
