evmPerRB = NaN(NRB, pdsch.NumLayers);
for nu = 1:pdsch.NumLayers
    for rb = unique(rbsubs).'
        this = (rbsubs == rb & p == nu);
        evmPerRB(rb + 1, nu) = rbEVM(pdschSymbols(this), pdschEq(this));
    end
end
plot(0:(NRB - 1), evmPerRB, 'x-');
xlabel('Resource block');
ylabel('EVM (%)');
legend("layer " + (1:pdsch.NumLayers), 'Location', 'EastOutside');
title(['EVM per layer per resource block, slot #' num2str(nslot)]);
drawnow;
end

function paddedArray = padWithNaN(array, desiredSize)
currentSize = size(array);
paddingSize = desiredSize - currentSize;
if paddingSize(1) > 0
    paddedArray = [array; NaN(paddingSize(1), currentSize(2))];
else
    paddedArray = array;
end
end

%% ---- NUEVAS funciones: modelo hibrido de propagacion LOS/NLOS ----

function [LOS, pathLossTotal, pLOS] = evaluatePropagation(txPosition, rxPosition, simParameters, mode)
% evaluatePropagation  Calcula LOS/NLOS y path loss para un enlace UAV-vehiculo.
%
%   mode = 'sampled'  -> obtiene una realizacion estocastica del estado
%                        LOS/NLOS (bernoulli con probabilidad pLOS) y
%                        devuelve el path loss correspondiente. Se usa
%                        para el enlace REAL (SNR/BLER/throughput).
%   mode = 'expected' -> devuelve un path loss determinista, mezcla
%                        ponderada por pLOS entre el path loss LOS y el
%                        NLOS. Se usa en la busqueda de trayectoria del
%                        UAV1 para evitar que el ruido de muestreo
%                        aleatorio haga que la optimizacion sea inestable.
if nargin < 4
    mode = 'sampled';
end

d2D = norm(txPosition(1:2) - rxPosition(1:2));

blocked = false;
if isfield(simParameters, 'Obstacle') && simParameters.Obstacle.Enable
    blocked = segmentIntersectsRect(txPosition(1:2), rxPosition(1:2), ...
        simParameters.Obstacle.X, simParameters.Obstacle.Y);
end

if blocked
    pLOS = 0;
elseif isfield(simParameters, 'UseProbabilisticLOS') && simParameters.UseProbabilisticLOS
    pLOS = probabilisticLOS_RMa(d2D);
else
    pLOS = 1;
end

plLOS  = nrPathLoss(simParameters.PathLoss, simParameters.CarrierFrequency, true,  txPosition, rxPosition);
plNLOS = nrPathLoss(simParameters.PathLoss, simParameters.CarrierFrequency, false, txPosition, rxPosition);

switch mode
    case 'expected'
        LOS = pLOS >= 0.5;
        pathLossTotal = pLOS * plLOS + (1 - pLOS) * plNLOS;
    otherwise % 'sampled'
        LOS = rand() < pLOS;
        if LOS
            pathLossTotal = plLOS;
        else
            pathLossTotal = plNLOS;
        end
end
end

function pLOS = probabilisticLOS_RMa(d2D)
% Modelo de probabilidad de LOS 3GPP TR38.901, escenario Rural Macro (RMa)
if d2D <= 10
    pLOS = 1;
else
    pLOS = exp(-(d2D - 10) / 1000);
end
end

function tf = segmentIntersectsRect(p1, p2, xRange, yRange)
% Verifica si el segmento p1-p2 (2D) intersecta el rectangulo del
% obstaculo definido por xRange = [xmin xmax], yRange = [ymin ymax]
x1 = p1(1); y1 = p1(2); x2 = p2(1); y2 = p2(2);
xmin = xRange(1); xmax = xRange(2); ymin = yRange(1); ymax = yRange(2);

if (x1 >= xmin && x1 <= xmax && y1 >= ymin && y1 <= ymax) || ...
   (x2 >= xmin && x2 <= xmax && y2 >= ymin && y2 <= ymax)
    tf = true;
    return;
end

edges = [xmin ymin xmax ymin;
         xmax ymin xmax ymax;
         xmax ymax xmin ymax;
         xmin ymax xmin ymin];

tf = false;
for e = 1:4
    if segmentsIntersect(x1, y1, x2, y2, edges(e,1), edges(e,2), edges(e,3), edges(e,4))
        tf = true;
        return;
    end
end
end

function tf = segmentsIntersect(x1, y1, x2, y2, x3, y3, x4, y4)
d1 = sign((x4-x3)*(y1-y3) - (y4-y3)*(x1-x3));
d2 = sign((x4-x3)*(y2-y3) - (y4-y3)*(x2-x3));
d3 = sign((x2-x1)*(y3-y1) - (y2-y1)*(x3-x1));
d4 = sign((x2-x1)*(y4-y1) - (y2-y1)*(x4-x1));
tf = (d1 ~= d2) && (d3 ~= d4);
end

function [shadowdB, stateOut] = updateShadowFading(vehicleID, rxPosition, sigma, corrDist, stateIn)
% Shadow fading log-normal espacialmente correlado (modelo autorregresivo
% de primer orden, correlacion exponencial con la distancia recorrida
% desde la ultima muestra de ese vehiculo).
if isKey(stateIn, vehicleID)
    prev = stateIn(vehicleID);
    d = norm(rxPosition(1:2) - prev.pos(1:2));
    rho = exp(-d / max(corrDist, eps));
    shadowdB = rho * prev.value + sqrt(max(1 - rho^2, 0)) * sigma * randn();
else
    shadowdB = sigma * randn();
end
newEntry.pos = rxPosition;
newEntry.value = shadowdB;
stateOut = stateIn;
stateOut(vehicleID) = newEntry;
end

function [localChannel, maxChDelayLocal] = buildLocalChannel(profileName, simParameters, waveformInfo)
% Construye un canal CDL propio para un enlace individual, con el perfil
% de retardo (CDL-D para LOS, CDL-A para NLOS, u otro configurado)
% correspondiente al estado LOS/NLOS de ese enlace en ese paso.
localChannel = nrCDLChannel;
localChannel = hArrayGeometry(localChannel, simParameters.NTxAnts, simParameters.NRxAnts);
localChannel.DelayProfile = profileName;
localChannel.DelaySpread = simParameters.DelaySpread;
localChannel.MaximumDopplerShift = simParameters.MaximumDopplerShift;
localChannel.SampleRate = waveformInfo.SampleRate;
chInfoLocal = info(localChannel);
maxChDelayLocal = chInfoLocal.MaximumChannelDelay;
end

function w = vehiclePriorityWeight(vehicleID)
% Asigna un peso de prioridad de QoS heterogeneo y determinista por
% vehiculo (p.ej. ~30% de los vehiculos representan usuarios
% prioritarios: transporte publico, servicios de emergencia, etc.)
% Usado solo cuando simParameters.UAV1Objective = 'weighted'.
h = sum(double(vehicleID));
if mod(h, 10) < 3
    w = 3;   % usuario prioritario
else
    w = 1;   % usuario estandar
end
end

